KG42.register("rules-ba7a672a80aee446aa19e1a4",{"id":"26-battery_flexibility::v141-c-R005","paper":"26-battery_flexibility","record":{"rule_id":"v141-c-R005","mechanism_id":"v141-a-M01","name":"Local clearing price","process_stage":"pricing","market_meaning":"The local P2P purchase price uses the house's willingness-to-pay shadow price from independently minimising each prosumer's electricity costs subject to the supply-demand balance, downscaled by 36% to exclude network and grid-usage fees. Scope: Flexi User local P2P purchase-price determination for each house and time step. Condition: The price-setting optimisation assumes no storage or interconnection; electricity traded locally is assumed not to incur grid-usage costs. The local P2P trade price is lower than the grid electricity price. Scope: Flexi User price assumptions for local P2P trade. Local P2P prices, as part of the model's non-grid prices, are determined from the exogenously given dynamic grid-price time series. Scope: Flexi User model assumptions governing local P2P price inputs. Local P2P prices exclude investment costs of distributed generation. Scope: Flexi User model assumptions applying to local P2P prices. The model does not represent uncertainty in local P2P prices. Scope: Flexi User model treatment of local P2P price uncertainty.","independence_rationale":"Relations governed by the approved function pricing.local under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["pricing.local"],"E":[],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"Flexi User local P2P purchase-price determination for each house and time step. | Flexi User model assumptions applying to local P2P prices. | Flexi User model assumptions governing local P2P price inputs. | Flexi User model treatment of local P2P price uncertainty. | Flexi User price assumptions for local P2P trade.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e08","v141-b-g01-e23","v141-b-g02-e16","v141-b-g02-e21"]},"x":[],"theta":[{"parameter_id":"p_G","symbol":"p_G","meaning":"Price of electricity from the grid in time step t; an exogenously given dynamic grid-price time series in the Flexi User pricing assumptions.","value":{"kind":"text","number_value":null,"text_value":"exogenous dynamic grid-price time series"},"unit":"pence/kWh (UK calibration reference)","indices":["t"],"evidence_ids":["v141-b-g01-e08","v141-b-g02-e21"]},{"parameter_id":"p_p2p","symbol":"p_{p2p}","meaning":"Price of electricity in the local P2P market for house h in time step t; implemented as the house's downscaled willingness-to-pay shadow price and constrained below the grid price.","value":{"kind":"symbolic","number_value":null,"text_value":"downscaled willingness-to-pay shadow price (exact arithmetic not stated)"},"unit":"same price unit as p_G (not separately stated in the rule evidence)","indices":["t","h"],"evidence_ids":["v141-b-g01-e08","v141-b-g02-e16"]},{"parameter_id":"p2p_downscale_fraction","symbol":"36\\%","meaning":"Stated percentage downscaling applied to the willingness-to-pay shadow price to remove network and grid-usage fees before using it as the local P2P purchase price; the source does not state whether the operation is p*(1-0.36) or another downscaling convention.","value":{"kind":"numeric","number_value":0.36,"text_value":null},"unit":"fraction","indices":[],"evidence_ids":["v141-b-g02-e16"]}],"phi":[{"constraint_id":"v141-c-R005-C001","kind":"procedural","role":"core","statement":"The local P2P purchase price uses the house's willingness-to-pay shadow price from independently minimising each prosumer's electricity costs subject to the supply-demand balance, downscaled by 36% to exclude network and grid-usage fees. Scope: Flexi User local P2P purchase-price determination for each house and time step. Condition: The price-setting optimisation assumes no storage or interconnection; electricity traded locally is assumed not to incur grid-usage costs.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local"],"variable_refs":[],"parameter_refs":["p_p2p","p_G","p2p_downscale_fraction"],"evidence_ids":["v141-b-g02-e16"]},{"constraint_id":"v141-c-R005-C002","kind":"mathematical","role":"core","statement":"The local P2P trade price is lower than the grid electricity price. Scope: Flexi User price assumptions for local P2P trade.","expression":"p_{p2p} \u003c p_G","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":[],"parameter_refs":["p_p2p","p_G"],"evidence_ids":["v141-b-g01-e08"]},{"constraint_id":"v141-c-R005-C003","kind":"procedural","role":"core","statement":"Local P2P prices, as part of the model's non-grid prices, are determined from the exogenously given dynamic grid-price time series. Scope: Flexi User model assumptions governing local P2P price inputs.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e21"]},{"constraint_id":"v141-c-R005-C004","kind":"procedural","role":"core","statement":"Local P2P prices exclude investment costs of distributed generation. Scope: Flexi User model assumptions applying to local P2P prices.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e23"]},{"constraint_id":"v141-c-R005-C005","kind":"procedural","role":"core","statement":"The model does not represent uncertainty in local P2P prices. Scope: Flexi User model treatment of local P2P price uncertainty.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e23"]}],"pi":[{"evidence_id":"v141-b-g01-e08","location":{"location_id":"src-9788b5496d-p05-c1r2__v141-a-M01-pricing","page":5,"printed_page":null,"section":"Table 2","anchor_text":"P2P trade price (pp2p ) P2P trade price (pp2p ) Prices: pp2p \u003c pG Discharge price (pD) ca Charge com","equation_id":null,"figure_id":null,"table_id":"Table 2","image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Flexi User — Prices: Grid price (p_G); P2P trade price (p_{p2p}); p_{p2p} \u003c p_G."},{"evidence_id":"v141-b-g01-e23","location":{"location_id":"src-9788b5496d-p05-c1r2__v141-a-M01-pricing","page":5,"printed_page":null,"section":"Table 2","anchor_text":"P2P trade price (pp2p ) P2P trade price (pp2p ) Prices: pp2p \u003c pG Discharge price (pD) ca Charge com","equation_id":null,"figure_id":null,"table_id":"Table 2","image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"In addition to the rules on storage, trade and prices defined in the market design, we need to make some assumptions with respect to model complexity and computational effort. We assume unlimited supply from the grid at any time. From the physical perspective, we neglect battery degradation and characteristics of electricity distribution, i.e. load flow. Investment costs of DG are not accounted for in any prices. Although we are aware of uncertainty in generation from RES, we do not consider any uncertainty in production or prices."},{"evidence_id":"v141-b-g02-e16","location":{"location_id":"src-9788b5496d-p07-c1r3__v141-a-M01-pricing","page":7,"printed_page":null,"section":"4.1.4 Electricity prices","anchor_text":"Fig. 3. Demand cover for exemplary houses on a scaled up to represent typical price levels customers","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"A reasonable price for P2P trade should reflect the willingness of each prosumer to pay for an extra unit of electricity under the assumption that there is no possibility for local trade or storage. The shadow price of each single prosumer can be seen as the willingness to pay of each prosumer. This approach is analogous to the proposition of Abbaspourtorbati et al. [45] who calculated clearing prices by the dual variables of the energy balance equations. To calculate the P2P prices, we independently minimise each prosumer’s costs for electricity subject to the supply-demand balance in Eq. (1) in the absence of storage and interconnection. The result of the separate optimisations provides a dynamic willingness to pay for electricity of each house in each time step. Since this P2P price should not consider the fees for network and grid usage (typically one third of the consumer bill, see [46]), we downscaled these prices by 36% as we assume that grid usage costs do not occur when electricity is traded locally in the community. Reflecting the willingness to pay for electricity, we implement these downscaled shadow prices as the house’s purchase price for P2P trade."},{"evidence_id":"v141-b-g02-e21","location":{"location_id":"src-9788b5496d-p06-c2r4__v141-a-M01-pricing","page":6,"printed_page":null,"section":"4.1.4 Electricity prices","anchor_text":"The optimisation and comparison of the proposed market designs al highly depend on the prices assume","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"The optimisation and comparison of the proposed market designs highly depend on the prices assumed to the different sources of electricity consumption (see Table 2). We use an exogenously given dynamic price for the grid and determine all other prices based on this dynamic time series. The time series of the reference price data (RPD) for the UK electricity spot market is retrieved from the former APX Group. The RPD accounts for about one thirds of the electricity bill the end-users pay in the UK. Consequently, the RPD time series was scaled up to represent typical price levels customers have to pay at the residential level. The average of the adjusted RPD time series was set to the flat rate of 14.2 pence/kWh that the customers in the static pricing scheme of the Low Carbon London project had to pay."}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":"No decision variable is defined by this pricing rule. The source classifies p_{p2p} and p_G as parameters (Table 1), and the rule's only explicit mathematics is a price ordering; C.1 supplied x=[].","empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-pricing","v141-a-M02-clearing","v141-a-M02-pricing"],"extras":{"decision_anchor":"pricing.local","graph_fact_supports":[[{"evidence_id":"v141-b-g02-e16","quote":"To calculate the P2P prices, we independently minimise each prosumer’s costs for electricity subject to the supply-demand balance in Eq. (1) in the absence of storage and interconnection. The result of the separate optimisations provides a dynamic willingness to pay for electricity of each house in each time step."},{"evidence_id":"v141-b-g02-e16","quote":"Since this P2P price should not consider the fees for network and grid usage (typically one third of the consumer bill, see [46]), we downscaled these prices by 36% as we assume that grid usage costs do not occur when electricity is traded locally in the community. Reflecting the willingness to pay for electricity, we implement these downscaled shadow prices as the house’s purchase price for P2P trade."}],[{"evidence_id":"v141-b-g01-e08","quote":"Flexi User — Prices: Grid price (p_G); P2P trade price (p_{p2p}); p_{p2p} \u003c p_G."}],[{"evidence_id":"v141-b-g02-e21","quote":"We use an exogenously given dynamic price for the grid and determine all other prices based on this dynamic time series."}],[{"evidence_id":"v141-b-g01-e23","quote":"Investment costs of DG are not accounted for in any prices."}],[{"evidence_id":"v141-b-g01-e23","quote":"Although we are aware of uncertainty in generation from RES, we do not consider any uncertainty in production or prices."}]],"C2_formalization":{"graph_sha256":"644e073fe1264beb1685ce207513fb6731d5213774390fd45fb19b415ccddb30","applicability":"needs_revision","reason":"Partial formalization from the supplied B extraction (unreviewed): the Flexi User price-ordering statement p_{p2p} \u003c p_G is explicitly supported and is formalized. The central rule that the local P2P purchase price equals a 36%-downscaled willingness-to-pay shadow price from independent prosumer cost minimisation cannot be written as a faithful source expression here: the supplied text gives no shadow-price symbol or equation, the exact arithmetic of 'downscaled ... by 36%' is ambiguous, and the frozen graph has only pricing.local with no edge representing the independent optimisation relation. The remaining C.1 procedural constraints are retained as not_formalized.","bindings":[{"object_id":"p_G","node_ids":["pricing.local"],"edge_ids":[],"rationale":"p_G is the grid electricity price parameter used in the Flexi User local P2P price ordering and pricing assumptions; the frozen rule owns pricing.local with no internal edges."},{"object_id":"p_p2p","node_ids":["pricing.local"],"edge_ids":[],"rationale":"p_{p2p} is the Flexi User local P2P trade price parameter; evidence defines it as the house-specific local purchase price and states the ordering with p_G."},{"object_id":"p2p_downscale_fraction","node_ids":["pricing.local"],"edge_ids":[],"rationale":"The 36% downscaling is a stated price-adjustment input for the local P2P purchase price; its exact arithmetic is not formalized, so it is bound to pricing.local only."},{"object_id":"v141-c-R005-C002","node_ids":["pricing.local"],"edge_ids":[],"rationale":"The formalized ordering p_{p2p} \u003c p_G is a unary Flexi User price-assumption fact attached to pricing.local; no graph edge is required or present."}],"revision_requests":["Provide the exact source symbol and equation for the willingness-to-pay shadow price per house and time step, and clarify the arithmetic of 'downscaled ... by 36%' (e.g., whether p_{p2p}=0.64*shadow_price or another operation). The supplied evidence describes but does not display this formula.","Confirm whether p_{p2p}^{(t,h)} and p_G^{(t)} should be declared as theta parameters in the frozen graph as Table 1 classifies them, and whether p_{p2p} is a parameter or a derived auxiliary price object. C.1 currently supplies theta=[] for this rule.","If the independent prosumer cost-minimisation relation is to be represented, add a graph edge/relationship between pricing.local and the appropriate clearing/optimisation node with evidence; the current frozen graph has V=['pricing.local'] and E=[].","Clarify the exact role, unit and domain of the 36% downscaling input if it is to remain a separate parameter object rather than only part of the not_formalized price-determination statement."]}},"quarantined_references":[]}});
